# -*- coding: utf-8 -*-
"""Residentado Médico 2020 · Anatomía Patológica, preguntas 26-50"""
import lote08_base as B
L = []
ROB = "Robbins y Cotran Patología Estructural y Funcional 10.ª ed. (2021)"
WHO_ST = "WHO Classification of Tumours, Soft Tissue and Bone Tumours 5.ª ed. (2020)"
WHO_HAEM = "Alaggio R et al. Leukemia 2022;36:1720-48 (WHO 5.ª ed. de neoplasias hematolinfoides)"
def Q(n, tema, cat, c, f, nota=None, **kw): B.hacer(L, "ANATOMIA_PATOLOGICA", n, tema, cat, c, f, nota, **kw)

Q(26, "Grado histológico del adenocarcinoma de colon", "Patología digestiva",
  "El grado histológico mide la diferenciación del tumor, es decir, cuánto se parece el tejido neoplásico al epitelio de origen, y es independiente de la extensión anatómica. En el adenocarcinoma colorrectal se gradúa según el porcentaje de formación glandular: bien diferenciado (más del 95 % de glándulas), moderadamente diferenciado (50-95 %) y pobremente diferenciado (menos del 50 %); la OMS simplifica en bajo y alto grado. Otros rasgos de agresividad, como el pleomorfismo nuclear, la actividad mitótica y la necrosis, acompañan a los tumores de alto grado, y por ello el recuento de figuras mitóticas por campo de gran aumento es el dato citológico que refleja la proliferación y se asocia al grado en la mayoría de las neoplasias. Las demás opciones pertenecen a la estadificación TNM y no al grado: el tamaño del tumor, la profundidad de invasión en la pared (pT), el número de ganglios positivos (pN) y las metástasis a distancia (pM). La estadificación predice el pronóstico y define la conducta adyuvante, por ejemplo quimioterapia en estadio III. Perla: en el cáncer de colon se recomienda examinar al menos 12 ganglios, y la inestabilidad de microsatélites se determina en todos los casos.",
  ROB + "; WHO Classification of Tumours, Digestive System Tumours 5.ª ed. (2019); Amin MB et al. AJCC Cancer Staging Manual 8.ª ed. (2017)",
  "En el colon el grado se basa sobre todo en la formación glandular; la clave oficial señala el recuento de mitosis como dato de grado, frente a las demás opciones que son de estadificación.")

Q(27, "Células NK frente a infección viral con baja expresión de CPH I", "Inmunología",
  "Muchos virus, entre ellos los de la gripe y los herpesvirus, disminuyen la expresión de moléculas del complejo mayor de histocompatibilidad de clase I en la célula infectada para escapar de los linfocitos T citotóxicos CD8+, que reconocen péptidos virales presentados por esas moléculas. Los linfocitos citolíticos naturales (NK) son los efectores de la inmunidad innata que resuelven esa maniobra: poseen receptores inhibidores (KIR y CD94/NKG2A) que reconocen CPH I propio y frenan su actividad, de modo que la pérdida de CPH I («reconocimiento de lo propio ausente») libera la inhibición y, junto con ligandos activadores inducidos por el estrés, desencadena la liberación de perforina y granzimas y la citotoxicidad dependiente de anticuerpos. Actúan en las primeras horas, antes de que se expanda la respuesta adaptativa, y secretan interferón gamma. Los linfocitos CD4+ colaboran con citocinas pero reconocen CPH II; los linfocitos B producen anticuerpos con retraso; los macrófagos fagocitan y presentan antígeno, pero no son los citotóxicos principales; las células dendríticas presentan antígeno y activan linfocitos T vírgenes. Perla: las células NK también eliminan células tumorales que han perdido CPH I.",
  ROB + "; Abbas AK et al. Inmunología Celular y Molecular 10.ª ed. (2022)")

Q(28, "Angiofibroma de células gigantes", "Patología de partes blandas y órbita",
  "El angiofibroma de células gigantes es una neoplasia mesenquimal benigna poco frecuente de la órbita, sobre todo de los párpados, en adultos de edad media. Histológicamente muestra un estroma de células fusiformes o redondeadas de aspecto inocuo, con celularidad variable, espacios angiectoides con paredes revestidas por células estromales multinucleadas y áreas de aspecto seudoangiomatoide, con cambios quísticos y hemorragia. Por inmunohistoquímica expresa CD34, con frecuencia CD99 y bcl-2, y es negativo para marcadores epiteliales y de músculo liso. Se considera la variante orbitaria del fibroblastoma de células gigantes, que pertenece a la misma familia que el dermatofibrosarcoma protuberans y comparte con él la positividad para CD34; sin embargo, el fibroblastoma de células gigantes afecta a niños y al tronco de varones jóvenes, y el dermatofibrosarcoma muestra patrón estoriforme y fusión COL1A1-PDGFB. El fibrohistiocitoma benigno es CD34 negativo y expresa factor XIIIa; el sarcoma sinovial monofásico tiene células fusiformes en fascículos con TLE1 y translocación t(X;18). El tratamiento es la escisión completa, y la recurrencia es poco habitual. Perla: la combinación de CD34 positivo, células gigantes multinucleadas y espacios vasculares en un tumor orbitario orienta a este diagnóstico.",
  WHO_ST + "",
  None)

Q(29, "Lipoblastoma", "Patología de partes blandas",
  "El lipoblastoma es un tumor adiposo benigno de la lactancia y la primera infancia, casi siempre antes de los 3 años y más frecuente en varones. Se origina de tejido adiposo embrionario y se presenta como una masa de crecimiento rápido en extremidades, tronco, cabeza y cuello, con una forma circunscrita y otra infiltrante llamada lipoblastomatosis. Microscópicamente está formado por lóbulos separados por tabiques fibrosos, con lipoblastos en distintas etapas de maduración, estroma mixoide con capilares en «pata de gallina» y adipocitos maduros; la presencia de áreas mixoides es característica. Se caracteriza genéticamente por reordenamientos del gen PLAG1 en 8q11-13. Es benigno: no metastatiza, no tiene transformación maligna y su pronóstico es excelente, de modo que las opciones sobre metástasis, malignización, mal pronóstico y ausencia de componente mixoide son falsas. El diagnóstico diferencial principal es el liposarcoma mixoide, raro en niños pequeños, que muestra translocación t(12;16) y FUS-DDIT3. El tratamiento es la escisión completa; la recidiva local aparece en cerca del 15-25 %, sobre todo en la forma infiltrante, y la maduración espontánea hacia lipoma puede ocurrir. Perla: ante un lipoma en un lactante, el diagnóstico más probable es lipoblastoma.",
  WHO_ST + "; " + ROB)

Q(30, "VPH de alto riesgo", "Patología ginecológica",
  "Los papilomavirus humanos se clasifican según su potencial oncogénico. Los tipos de alto riesgo comprenden 16, 18, 31, 33, 35, 39, 45, 51, 52, 56, 58, 59, 66 y 68, a los que la IARC añade otros de probable riesgo. Estos genotipos expresan las oncoproteínas E6 y E7 que inactivan p53 y la proteína del retinoblastoma (Rb), lo que altera el control del ciclo celular, y se integran al genoma del huésped; el VPH 16 se asocia con cerca del 50-60 % de los carcinomas de cuello uterino y el 18 con el adenocarcinoma. El tipo 31 es de alto riesgo y produce lesión intraepitelial escamosa de alto grado y carcinoma. Los tipos 6 y 11 son de bajo riesgo y causan condilomas acuminados y papilomatosis respiratoria recurrente, mientras que los tipos 40 y 42 también se agrupan entre los de bajo riesgo y se asocian con lesiones benignas anogenitales. El tamizaje se hace con prueba de VPH o citología, y la vacunación nonavalente cubre los tipos 6, 11, 16, 18, 31, 33, 45, 52 y 58. Perla: la infección persistente por un tipo de alto riesgo, y no la transitoria, es la que conduce al cáncer.",
  ROB + "; Muñoz N et al. N Engl J Med 2003;348:518-27 (clasificación epidemiológica de los tipos de VPH); Directiva 165-2025 (cáncer de cuello uterino)")

Q(31, "Endometriosis vesical", "Patología ginecológica",
  "La endometriosis es la presencia de glándulas y estroma endometrial fuera del útero. Su localización vesical es poco común y se manifiesta con hematuria cíclica durante la menstruación en una mujer en edad reproductiva, a menudo con dolor suprapúbico o abdominal también cíclico. La causa propuesta incluye la menstruación retrógrada, la metaplasia celómica y la diseminación linfática o vascular. Al ser tejido sensible a las hormonas ováricas, sangra con cada ciclo, y por eso el examen histológico revela glándulas endometriales, estroma y macrófagos con hemosiderina, que son el signo de hemorragia repetida; la cistoscopia muestra un nódulo azulado o violáceo en la cúpula vesical. Las demás opciones no explican la ciclicidad: los fascículos entrelazados de músculo liso corresponden a un leiomioma, los pólipos revestidos de células neoplásicas a un carcinoma urotelial papilar, que se asocia al tabaco y no tiene relación con la menstruación; el Schistosoma haematobium produce hematuria en zonas endémicas sin ciclicidad, y las calcificaciones displásicas no son específicas. El tratamiento incluye supresión hormonal y resección transuretral o cistectomía parcial. Perla: hematuria que coincide con la regla equivale a endometriosis hasta que se demuestre lo contrario.",
  ROB + "; Williams Ginecología 4.ª ed. (2020); Zondervan KT et al. N Engl J Med 2020;382:1244-56")

Q(32, "Quiste periapical", "Patología oral",
  "El quiste periapical (radicular) es el quiste odontogénico inflamatorio más frecuente de los maxilares. Se origina por la proliferación de los restos epiteliales de Malassez, estimulados por la inflamación crónica periapical que sigue a la necrosis pulpar de un diente con caries profunda o traumatismo. Aparece como una imagen radiolúcida circunscrita en el ápice de un diente desvitalizado, con pérdida de la lámina dura, y en el maxilar superior afecta con mayor frecuencia a los incisivos. Histológicamente la cápsula de tejido fibroso contiene un denso infiltrado inflamatorio crónico, y el revestimiento es de epitelio escamoso estratificado no queratinizado; son comunes los cristales de colesterol, los cuerpos de Rushton y la calcificación distrófica. El quiste periodontal lateral aparece en el lado de la raíz de un diente vital y su epitelio es delgado y claro; el quiste del conducto nasopalatino se halla en la línea media, entre los incisivos centrales, con epitelio variable y vasos y nervios en la pared; el quiste ortoqueratinizante y el tumor odontogénico queratoquístico tienen una capa queratinizada ondulada con empalizada basal. Perla: el tratamiento es endodoncia o extracción, con enucleación del quiste y apicectomía si persiste.",
  ROB + "; WHO Classification of Head and Neck Tumours 5.ª ed. (2022); Neville BW et al. Oral and Maxillofacial Pathology 4.ª ed. (2016)")

Q(33, "Clasificación FAB de la leucemia mieloide aguda", "Hematopatología",
  "La clasificación franco-americano-británica (FAB) divide las leucemias mieloides agudas (LMA) en ocho subtipos según la morfología y la citoquímica de los blastos. M0 es la LMA mínimamente diferenciada, sin mieloperoxidasa por citoquímica; M1 es la LMA sin maduración, con 90 % o más de blastos mieloides en la médula no eritroide y menos del 10 % de células maduras, y los blastos son positivos para mieloperoxidasa; M2 es la LMA con maduración, que incluye la t(8;21); M3 es la leucemia promielocítica con t(15;17) y PML-RARA; M4 la mielomonocítica, M4eo con inv(16); M5 la monocítica, M6 la eritroide y M7 la megacarioblástica. Por ello la LMA sin maduración corresponde a M1. La clasificación actual de la OMS (2016, y la 5.ª edición de 2022) y la ICC se basa en anomalías genéticas recurrentes y en un umbral de blastos, y no sigue el esquema FAB, aunque este persiste en la terminología. El diagnóstico exige citometría de flujo, citogenética y biología molecular, y los bastones de Auer son típicos. Perla: la M3 es una urgencia por coagulopatía, y se trata de inmediato con ácido transretinoico.",
  ROB + "; Bennett JM et al. Br J Haematol 1976;33:451-8 (clasificación FAB); Arber DA et al. Blood 2016;127:2391-405; " + WHO_HAEM)

Q(34, "Mutación SF3B1 en el síndrome mielodisplásico", "Hematopatología",
  "Los síndromes mielodisplásicos son neoplasias clonales de la célula madre hematopoyética con hematopoyesis ineficaz, displasia y riesgo de evolución a leucemia. Las mutaciones de los genes del empalme (splicing) son frecuentes; la mutación de SF3B1 se asocia con sideroblastos en anillo y con displasia eritroide aislada, y confiere un pronóstico favorable, con supervivencia prolongada y bajo riesgo de transformación leucémica. La clasificación de la OMS 2022 reconoce el síndrome mielodisplásico con mutación de SF3B1 como entidad propia. Responde bien a luspatercept, un agente que mejora la maduración eritroide. Las otras mutaciones se asocian con pronóstico desfavorable: TP53, sobre todo la multi-hit, indica alto riesgo, resistencia a terapia y evolución rápida; RUNX1 y NRAS se relacionan con progresión a leucemia y supervivencia más corta; SRSF2, también del empalme, se vincula con leucemia mielomonocítica crónica y con peor pronóstico. El índice pronóstico IPSS-M (2022) integra las mutaciones con la citopenia y la citogenética. Perla: en un paciente con anemia macrocítica y sideroblastos en anillo, se busca mutación SF3B1, que predice una evolución indolente.",
  "Papaemmanuil E et al. Blood 2013;122:3616-27; Malcovati L et al. Blood 2015;126:233-41; Bernard E et al. NEJM Evid 2022;1(7):EVIDoa2200008 (IPSS-M); " + WHO_HAEM)

Q(35, "Neurofibroma difuso", "Patología de nervios periféricos",
  "El neurofibroma es una neoplasia benigna de la vaina nerviosa formada por células de Schwann, fibroblastos, células perineurales, mastocitos y matriz colágena mixoide, con un patrón de fibras de colágeno «en alambre» o «en zanahoria». Existen cuatro variantes: localizado, difuso, plexiforme y masivo de partes blandas. El neurofibroma difuso ocurre en niños y adultos jóvenes, afecta a la dermis y al tejido subcutáneo de cabeza y cuello, y forma una placa que infiltra los septos y rodea los anexos sin destruirlos, con aspecto de «panal». Su rasgo característico es la presencia de estructuras seudotáctiles, es decir, corpúsculos de Wagner-Meissner, que se detectan dentro del tumor en cerca del 40 % de los casos. Los múltiples nódulos intraneurales corresponden al neurofibroma plexiforme, patognomónico de neurofibromatosis tipo 1; el cambio mixoide es común a muchos tumores, y la disposición estoriforme, la hialinización y los patrones en espiral son propios del dermatofibrosarcoma protuberans y del fibroxantoma. Perla: el neurofibroma plexiforme puede malignizarse a tumor maligno de la vaina nerviosa periférica, y el difuso casi no lo hace.",
  WHO_ST + "; " + ROB)

Q(36, "Struma ovarii", "Patología ovárica",
  "El struma ovarii es un teratoma monodérmico especializado en el que el tejido tiroideo maduro constituye más del 50 % del tumor. Aparece en mujeres de edad media, es unilateral y se presenta como una tumoración sólido-quística con áreas multiloculadas de contenido coloide, a menudo de color pardo verdoso. Microscópicamente reproduce folículos tiroideos con coloide, macro y microfolículos, y las células foliculares, planas o cúbicas, de citoplasma pálido o eosinofílico, tienen núcleos redondos u ovales uniformes. Es benigno en la gran mayoría, y puede acompañarse de hipertiroidismo (cerca del 5-8 %) o ascitis (síndrome de pseudo-Meigs). Raras veces se transforma en carcinoma papilar de tiroides. El disgerminoma muestra células claras en nidos con septos linfocitarios; el teratoma inmaduro posee neuroepitelio inmaduro; el tumor de Sertoli-Leydig produce andrógenos y recuerda túbulos testiculares; el tumor del saco vitelino exhibe patrón reticular, cuerpos de Schiller-Duval y alfafetoproteína. Se confirma con tiroglobulina y TTF-1. Perla: ante hipertiroidismo con tiroides gammagráficamente hipocaptante y masa pélvica, se sospecha struma ovarii.",
  "WHO Classification of Tumours, Female Genital Tumours 5.ª ed. (2020); " + ROB,
  "El enunciado dice «Struma ovarri» y «Sertoli-Leyding»: son errores de ortografía de la fuente; el diagnóstico es struma ovarii.")

Q(37, "Inmunohistoquímica del tumor del saco vitelino", "Patología testicular y ovárica",
  "El tumor del saco vitelino (tumor del seno endodérmico) es una neoplasia de células germinales que recuerda el saco vitelino embrionario, frecuente en niños pequeños en el testículo y en mujeres jóvenes en el ovario, y como componente de tumores mixtos del adulto. Los patrones son reticular o microquístico, festoneado, papilar y sólido, y son típicos los cuerpos de Schiller-Duval y los glóbulos hialinos eosinófilos. Sintetiza alfafetoproteína (AFP), que se detecta tanto en sangre como en los tejidos, y es el hallazgo inmunohistoquímico y marcador tumoral más característico. También es positivo para glipicano 3 y SALL4 y negativo para OCT4, CD30 y CD117 (KIT). SALL4 es un marcador sensible de todos los tumores de células germinales, pero no específico del saco vitelino; CD117 se expresa en el seminoma y el disgerminoma; CD30 marca el carcinoma embrionario; el EMA no es un marcador germinal, pues suele ser negativo. Los tumores de saco vitelino son muy sensibles a la quimioterapia con bleomicina, etopósido y cisplatino (BEP). Perla: una AFP elevada en un tumor testicular que parece seminoma puro indica componente no seminomatoso.",
  "WHO Classification of Tumours, Urinary and Male Genital Tumours 5.ª ed. (2022); " + ROB)

Q(38, "Insulitis en la diabetes tipo 1", "Patología endocrina",
  "La diabetes mellitus tipo 1 es una enfermedad autoinmunitaria que destruye de manera selectiva las células beta de los islotes pancreáticos, mediada por linfocitos T CD4+ y CD8+ frente a autoantígenos como la insulina, GAD65 e IA-2, en un contexto de susceptibilidad genética (HLA-DR3 y DR4) y factores ambientales. La lesión característica de la fase inicial es la insulitis, un infiltrado de linfocitos T, con macrófagos y algunos linfocitos B, dentro y alrededor de los islotes. Al avanzar la enfermedad los islotes se atrofian y se reduce el número de células beta, hasta cerca del 80-90 % de pérdida al diagnóstico clínico. El depósito de amiloide en los islotes es propio de la diabetes tipo 2; la calcificación distrófica y la necrosis grasa se observan en la pancreatitis aguda o crónica; un mayor número de islotes aparece en hijos de madre diabética, y la fibrosis acinar con atrofia corresponde a la pancreatitis crónica. El tratamiento es la insulina, con control glucémico y vigilancia de complicaciones; los anticuerpos antiGAD son útiles para el diagnóstico. Perla: los anticuerpos, y no la insulitis, son lo que se mide en la práctica.",
  ROB + "; American Diabetes Association. Diabetes Care 2024;47(Suppl 1):S20-S42 (clasificación y diagnóstico)")

Q(39, "Sarcoma de Kaposi y HHV-8", "Patología vascular e infecciosa",
  "El sarcoma de Kaposi es una neoplasia vascular de bajo grado causada por el herpesvirus humano 8 (HHV-8, herpesvirus asociado al sarcoma de Kaposi). Existen cuatro formas: clásica, endémica africana, iatrogénica y epidémica asociada al sida, que es la que afecta a un varón homosexual con inmunodepresión. Evoluciona en tres fases: mácula o parche, placa y nódulo. La fase de mácula, descrita en el caso, muestra espacios capilares irregulares y angulados, revestidos por células endoteliales con leve pleomorfismo nuclear, que rodean los vasos dérmicos preexistentes (signo del promontorio), con extravasación de eritrocitos, macrófagos con hemosiderina y células inflamatorias mononucleares. La inmunohistoquímica es positiva para LANA-1 del HHV-8, CD31 y CD34, y la proteína se expresa en la fase de placa y nodular con células fusiformes. El virus herpes simple y el citomegalovirus producen lesiones ulcerosas y de inclusiones, el VHH-6 se vincula con exantema súbito, y el VIH favorece el tumor pero no lo causa directamente. El tratamiento principal es la terapia antirretroviral, además de quimioterapia liposomal con antraciclinas si hay enfermedad extensa. Perla: el sarcoma de Kaposi es una enfermedad definitoria de sida.",
  ROB + "; Cesarman E et al. Nat Rev Dis Primers 2019;5:9 (sarcoma de Kaposi); NTS 169-MINSA/2020/DGIESP (VIH)")

Q(40, "Hiperdiploidía en leucemia linfoblástica aguda", "Hematopatología",
  "La leucemia linfoblástica aguda de células B es la neoplasia más frecuente de la infancia, y su pronóstico depende de la edad, el recuento de leucocitos y las alteraciones citogenéticas de los blastos. La hiperdiploidía (más de 50 cromosomas, con ganancias de los cromosomas 4, 10, 17 y 18) y la t(12;21) con fusión ETV6-RUNX1 son los hallazgos de pronóstico favorable, con supervivencia superior al 90 % con quimioterapia moderna. El 25 % de los casos pediátricos es hiperdiploide y se asocia con edad de 2 a 10 años. Por ello la respuesta es la hiperdiploidía. Los cambios de mal pronóstico incluyen el reordenamiento 11q23 (KMT2A), típico del lactante, la t(9;22) o cromosoma Filadelfia (BCR-ABL1), que se trata con inhibidores de tirosina cinasa asociados a quimioterapia, la hipodiploidía (menos de 44 cromosomas, con TP53 mutado), el iAMP21 y, con valor intermedio o adverso, la t(1;19) (TCF3-PBX1), que ha mejorado con terapia intensificada. La respuesta temprana y la enfermedad mínima residual son factores determinantes. Perla: la t(12;21) no se ve en el cariotipo convencional, requiere FISH o PCR.",
  "Pui CH, Evans WE. N Engl J Med 2006;354:166-78; Moorman AV et al. Lancet Oncol 2010;11:429-38; " + WHO_HAEM)

Q(41, "AMACR en el carcinoma renal papilar", "Patología renal",
  "La alfa-metilacil-CoA racemasa (AMACR, P504S) es una enzima mitocondrial y peroxisomal de la oxidación de ácidos grasos que se sobreexpresa en el adenocarcinoma de próstata y se utiliza como marcador inmunohistoquímico. En los tumores renales se expresa de manera difusa y fuerte en el carcinoma papilar de células renales, tanto en el tipo 1 como en el tipo 2, con un patrón citoplásmico granular, por lo que ayuda a distinguirlo de otros subtipos. Se acompaña de positividad para CK7 en el tipo 1 y trisomía de los cromosomas 7 y 17 o pérdida de Y. El carcinoma de células claras, el más frecuente, es positivo para anhidrasa carbónica IX, CD10 y PAX8 y negativo o focal para AMACR; el carcinoma cromófobo muestra positividad para CD117, CK7 y CD10 débil, con AMACR negativo; el carcinoma de los conductos colectores es agresivo, con patrón tubular desmoplásico y expresión de UEA-1, y el carcinoma medular renal se asocia con hemoglobinopatía falciforme, con pérdida de INI1 (SMARCB1). Perla: el carcinoma papilar de tipo 1 se asocia con mutación de MET, y el hereditario con carcinoma papilar hereditario.",
  "Moch H et al. Eur Urol 2016;70:93-105 (clasificación OMS de tumores renales 2016); WHO Classification of Tumours, Urinary and Male Genital Tumours 5.ª ed. (2022); " + ROB)

Q(42, "Síndrome de Gilbert", "Patología hepática",
  "El síndrome de Gilbert es la causa más frecuente de hiperbilirrubinemia indirecta hereditaria benigna, y afecta al 5-10 % de la población. Se debe a una disminución de la actividad de la enzima UDP-glucuronosiltransferasa 1A1 (UGT1A1) por una expansión repetida TA en su promotor (UGT1A1*28), con una conjugación hepática reducida de bilirrubina. Los pacientes tienen ictericia leve e intermitente, que aparece con ayuno, estrés, enfermedad intercurrente o ejercicio, con bilirrubina total que suele ser menor de 5 mg/dl a expensas de la fracción no conjugada. Como la bilirrubina indirecta se une a la albúmina y no se filtra por el glomérulo, la tira de orina no muestra bilirrubina (acolúria), y las transaminasas, la fosfatasa alcalina y el hemograma son normales. Por eso la biopsia hepática, que no se requiere, muestra parénquima normal. Las demás opciones corresponden a otras entidades: el puente fibroso es de cirrosis; la necrosis de hepatocitos, de hepatitis aguda; el aumento de hierro, de hemocromatosis; y la invasión linfocítica del tracto portal, de hepatitis crónica viral o de cirrosis biliar primaria. El diagnóstico es clínico y no requiere tratamiento. Perla: el síndrome de Crigler-Najjar causa ictericia grave neonatal y tiene un déficit mayor de la enzima.",
  ROB + "; Harrison Principios de Medicina Interna 21.ª ed. (2022)")

Q(43, "Isocromosoma 12p en tumores germinales", "Patología testicular",
  "Los tumores de células germinales testiculares del adulto derivan de la neoplasia de células germinales in situ y comparten una alteración citogenética casi constante: el isocromosoma del brazo corto del cromosoma 12, i(12p), o la ganancia del 12p, presente en cerca del 80 % de los casos, independientemente del subtipo histológico. Ello apoya el origen común del seminoma, el carcinoma embrionario, el tumor del saco vitelino, el coriocarcinoma y el teratoma. El caso describe un tumor mixto de células germinales en un varón joven con inflamación indolora de testículo, que es el cuadro típico. Los otros brazos cromosómicos no son característicos de estos tumores. La estadificación incluye marcadores séricos (AFP, beta-hCG y LDH), y el coriocarcinoma eleva la gonadotropina coriónica, con riesgo de ginecomastia y diseminación hematógena temprana a pulmón. El tratamiento es la orquiectomía radical por vía inguinal, sin biopsia transescrotal, seguida de vigilancia o quimioterapia según el estadio, con regímenes basados en cisplatino (BEP). Perla: el seminoma puro no eleva la AFP, y los tumores de mayor riesgo de metástasis temprana son los coriocarcinomas.",
  "Oosterhuis JW, Looijenga LHJ. Nat Rev Cancer 2005;5:210-22; WHO Classification of Tumours, Urinary and Male Genital Tumours 5.ª ed. (2022); " + ROB)

Q(44, "Actinomicosis y dispositivo intrauterino", "Patología ginecológica e infecciosa",
  "Actinomyces israelii y otras especies son bacilos grampositivos anaerobios o microaerófilos, ramificados, que forman parte de la flora de la boca, el tubo digestivo y, con menor frecuencia, el tracto genital femenino. No es común que causen enfermedad, pero la barrera mucosa dañada o un cuerpo extraño favorecen la infección. El dispositivo intrauterino, sobre todo cuando se mantiene durante años, actúa como un cuerpo extraño que crea un microambiente de baja tensión de oxígeno en la superficie y en la biopelícula, y facilita la colonización por Actinomyces, lo que explica la respuesta correcta. La colonización suele ser asintomática y se detecta en la citología cervical como colonias filamentosas con aspecto de «bola de algodón»; la infección invasiva produce enfermedad inflamatoria pélvica, absceso tuboovárico y fístulas con gránulos de azufre. Los otros mecanismos son inverosímiles: no hay intercambio de proteoglucanos entre membranas ni transporte de entactina ni ruptura de la bicapa lipídica, y la respuesta a cuerpo extraño por sí sola no explica la colonización anaerobia. El tratamiento es penicilina G, seguida de amoxicilina durante varios meses, y el retiro del dispositivo. Perla: sin síntomas, el hallazgo citológico no obliga a retirar el DIU.",
  ROB + "; Valour F et al. Infect Drug Resist 2014;7:183-97 (actinomicosis); Williams Ginecología 4.ª ed. (2020)",
  "Opciones redactadas de forma poco precisa; la clave oficial es el microambiente anaerobio creado por el cuerpo extraño.")

Q(45, "Tiroides estimulada por TSH", "Patología endocrina",
  "La TSH se une a su receptor acoplado a proteína Gs en la membrana basolateral de las células foliculares y activa la adenilato ciclasa, con aumento del AMP cíclico. Esto estimula la captación de yoduro por el cotransportador sodio-yoduro, la síntesis de tiroglobulina, la yodación y, además, el crecimiento celular. La glándula estimulada tiene células foliculares altas, en forma de columna (cilíndricas), con hipertrofia e hiperplasia, formando papilas hacia la luz, coloide escaso con bordes festoneados por reabsorción activa y mayor vascularización, como ocurre en la enfermedad de Graves, donde el estímulo proviene de anticuerpos contra el receptor de TSH. En la glándula en reposo o inhibida, las células son planas o cúbicas, los folículos grandes y el coloide abundante; por tanto, la abundancia de coloide en la luz no corresponde a la estimulación. Las células foliculares aumentan, no se reducen; las células parafoliculares (C) producen calcitonina y no responden a TSH, y los capilares perifoliculares aumentan por el efecto trófico. El estudio se realiza con TSH, T4 libre y anticuerpos. Perla: el bocio por déficit de yodo resulta de la estimulación crónica por TSH ante una T4 baja.",
  ROB + "; Guyton y Hall Tratado de Fisiología Médica 14.ª ed. (2021)")

Q(46, "Pronóstico de los linfomas: ALCL ALK positivo", "Hematopatología",
  "El linfoma anaplásico de células grandes con translocación de ALK (t(2;5), NPM-ALK) es un linfoma T periférico de personas jóvenes, con células grandes de aspecto pleomórfico, núcleos en herradura (células «hallmark») y expresión fuerte de CD30 y de ALK, con frecuencia extraganglionar y síntomas B. A diferencia de otros linfomas T, tiene un pronóstico favorable, con supervivencia a 5 años cercana al 70-90 %, superior a la del tipo ALK negativo (cerca del 40-50 %), y responde bien a CHOP o a brentuximab vedotina combinado. El linfoma linfoplasmocítico (macroglobulinemia de Waldenström, MYD88 L265P), el linfoma de la zona marginal y el linfoma de células del manto (t(11;14), ciclina D1) tienen evolución indolente o intermedia, pero rara vez se curan: el de células del manto tiene supervivencia mediana de 4 a 8 años en pacientes no jóvenes, y los otros son crónicos con recaídas. El linfoma de Burkitt (t(8;14) y MYC) es de alta agresividad y requiere quimioterapia intensiva, que logra curación en niños pero con menor supervivencia en adultos mayores. Perla: la expresión de ALK es un factor pronóstico favorable en el linfoma anaplásico.",
  WHO_HAEM + "; Savage KJ et al. Blood 2008;111:5496-504",
  "Pregunta comparativa de supervivencia; el linfoma de la zona marginal y el linfoplasmocítico tienen buena supervivencia, pero la clave oficial es el ALCL ALK positivo.")

Q(47, "Duodenitis péptica", "Patología digestiva",
  "La duodenitis péptica es la lesión inflamatoria del bulbo duodenal causada por la agresión del ácido gástrico, a menudo asociada a infección por Helicobacter pylori o uso de AINE. La hipersecreción ácida sobrepasa la capacidad de neutralización del bicarbonato duodenal, y el epitelio responde con metaplasia gástrica (epitelio de tipo foveolar en el bulbo), que es el rasgo histológico clave, y puede ser colonizada por H. pylori. Los hallazgos del caso la caracterizan: aplanamiento velloso focal por lesión del epitelio, infiltrado de neutrófilos y plasmocitos en la lámina propia, e hiperplasia de glándulas de Brunner, que secretan moco alcalino. La clínica incluye dolor epigástrico y hemorragia digestiva alta. La enfermedad celíaca muestra atrofia vellosa difusa con linfocitosis intraepitelial y hiperplasia de criptas, sobre todo en el duodeno distal; la enfermedad de Crohn, granulomas no caseificantes e inflamación transmural; el esprúe tropical, atrofia con inflamación en residentes de zonas tropicales, y la macroglobulinemia de Waldenström, infiltración por linfocitos plasmocitoides con IgM. El tratamiento consiste en inhibidores de la bomba de protones y erradicación de H. pylori. Perla: la metaplasia gástrica duodenal es una respuesta a la agresión ácida.",
  ROB + "; Sabiston Tratado de Cirugía 21.ª ed. (2021)")

Q(48, "Hipotiroidismo congénito (cretinismo)", "Patología endocrina",
  "El hipotiroidismo congénito no tratado, antes llamado cretinismo, es la causa prevenible más importante de discapacidad intelectual. La hormona tiroidea (tiroxina, T4, y su forma activa T3) es indispensable para la maduración del sistema nervioso central, con mielinización, desarrollo de dendritas y migración neuronal, en el último trimestre del embarazo y los primeros años de vida, y para el crecimiento óseo. Su ausencia produce retraso del crecimiento, talla baja, rasgos faciales toscos con macroglosia (protrusión de la lengua), hernia umbilical, piel seca, ictericia prolongada, estreñimiento e hipotonía, y discapacidad intelectual grave si el tratamiento se retrasa. Las causas son disgenesia tiroidea, el defecto de la síntesis hormonal (dishormonogénesis) y, en áreas endémicas, la deficiencia de yodo. La deficiencia de cortisol causa hipoglucemia y colapso; la de noradrenalina no se asocia a un síndrome así; la somatostatina inhibe hormonas, y la deficiencia de insulina produce hiperglucemia. El tamizaje neonatal mide TSH en sangre del talón antes del séptimo día, según la NTS 154-MINSA/2019/DGIESP, y el tratamiento con levotiroxina desde las primeras 2 semanas evita las secuelas. Perla: los síntomas aparecen después de los 2-3 meses, por lo que sin tamizaje se pierde la ventana terapéutica.",
  ROB + "; Nelson Tratado de Pediatría 22.ª ed. (2024); NTS 154-MINSA/2019/DGIESP (tamizaje neonatal)")

Q(49, "Leucemia de células peludas", "Hematopatología",
  "La leucemia de células peludas es una neoplasia indolente de linfocitos B maduros de la zona externa, que predomina en varones de edad media, aunque el caso describe a una mujer, con pancitopenia, esplenomegalia masiva sin adenopatías y monocitopenia característica. Se debe a la mutación BRAF V600E, presente en casi todos los casos. En el bazo infiltra la pulpa roja de forma difusa, con células de citoplasma claro y prolongaciones («peludas»), y la médula es difícil de aspirar («punción seca») por fibrosis reticulínica. El fenotipo es CD20, CD11c, CD103, CD25, anexina A1, TRAP y CD123 positivos, lo que corresponde al caso y distingue la entidad. La leucemia mieloide crónica tiene BCR-ABL y granulocitos inmaduros; el linfoma difuso de células B grandes forma masas con células grandes; la leucemia linfocítica crónica expresa CD5 y CD23; y el linfoma esplénico con linfocitos vellosos (zona marginal) es CD11c variable, CD103 y anexina A1 negativas, y afecta la pulpa blanca. El tratamiento es cladribina o pentostatina, con remisión en más del 85 %, y vemurafenib en recaídas. Perla: la anexina A1 es el marcador más específico frente a otros linfomas B.",
  "Tiacci E et al. N Engl J Med 2011;364:2305-15 (BRAF V600E en la leucemia de células peludas); " + WHO_HAEM + "; " + ROB)

Q(50, "Eritema nodoso", "Dermatopatología",
  "El eritema nodoso es la paniculitis más frecuente. Es una reacción de hipersensibilidad tardía a diversos estímulos y se presenta como nódulos dolorosos, eritematosos y calientes en la cara anterior de las piernas, en mujeres jóvenes, a veces con fiebre y artralgias; por lo tanto, no se localiza en la cara. Histológicamente es una paniculitis septal sin vasculitis: los septos del tejido adiposo subcutáneo se ensanchan por edema, infiltrado de linfocitos, histiocitos y neutrófilos, con granulomas de Miescher radiales (histiocitos alrededor de una hendidura), mientras que el lobulillo graso se conserva. No es una anaerobiosis granulomatosa ni una paniculitis lobulillar; esta última corresponde a la paniculitis por déficit de alfa-1 antitripsina, la lúpica y la necrosis grasa. Las causas más comunes son infecciones estreptocócicas, tuberculosis y otras micobacteriosis, sarcoidosis (síndrome de Löfgren), enfermedad inflamatoria intestinal, fármacos (anticonceptivos orales, sulfonamidas) y embarazo; en muchos casos es idiopático. El tratamiento consiste en tratar la causa, reposo, AINE y yoduro de potasio, y suele resolverse en 3-6 semanas sin cicatriz ni ulceración. Perla: ante un eritema nodoso, se investiga estreptococo, tuberculosis y sarcoidosis.",
  ROB + "; Requena L, Yus ES. J Am Acad Dermatol 2001;45:163-83 (eritema nodoso)")
